parameters.jsCode:
// Fan out one item per target App Store country code
return $input.first().json.countries
  .split(',')
  .map(code => code.trim())
  .filter(code => code.length > 0)
  .map(code => ({ json: { country_code: code } }));

const cutoffTime = new Date();
cutoffTime.setDate(cutoffTime.getDate() - Number.parseInt($('Configure AppID, LookbackWindow').first().json.lookbackDays));

const parsedReviews = [];
const feeds = $input.all();

for (let i = 0; i < feeds.length; i++) {
  const countryCode = $('Split Out Countries').itemMatching(i).json.country_code;
  const jsonData = JSON.parse(feeds[i].json.data);
  const reviews = jsonData.feed.entry || [];

  for (const review of reviews) {
    const updated = review.updated?.label || '';
    if (!updated || new Date(updated) < cutoffTime) continue;

    parsedReviews.push({
      json: {
        // Author information
        author_name: review.author?.name?.label || '',
        author_uri: review.author?.uri?.label || '',

        // Review metadata
        review_id: review.id?.label || '',
        title: review.title?.label || '',
        rating: review['im:rating']?.label || '',
        version: review['im:version']?.label || '',

        // Review content
        content: review.content?.label || '',

        // Timestamps
        updated: updated,

        // Engagement metrics
        vote_sum: review['im:voteSum']?.label || '0',
        vote_count: review['im:voteCount']?.label || '0',

        // Additional info
        content_type: review['im:contentType']?.attributes?.label || '',
        review_link: review.link?.attributes?.href || '',

        country_code: countryCode
      }
    });
  }
}

return parsedReviews;
